#!/usr/bin/env bash
# Sample MySQL TPG source for the `dev` profile (US-113): synthetic data only, never client data.
# tela_ro may read the extract (SELECT, SHOW VIEW on tpg.*) and nothing else (RULE-001).
# 01-data.sql is generated by deploy/compose/dev-setup.sh from packs/pmo/fixtures/tpg_synthetic.py.
set -euo pipefail
ro_pw="$(cat /run/secrets/sample_mysql_ro_password)"
mysql -uroot -p"$(cat /run/secrets/sample_mysql_root_password)" <<SQL
CREATE USER IF NOT EXISTS 'tela_ro'@'%' IDENTIFIED BY '${ro_pw}';
GRANT SELECT, SHOW VIEW ON tpg.* TO 'tela_ro'@'%';
SQL
